function ForgingChallengePopup:__init()
    self.selectedChallengeIndex = 0--当前选择的制造关卡索引
    self.forgingQuestVo = {}--制造关卡表
    self.curForgingGrade = 0--玩家当前的制造等级

end

function ForgingChallengePopup:__delete()
    self.selectedChallengeIndex = nil
    self.forgingQuestVo = nil
    self.curForgingGrade = nil

