function ForgingChallengePopup:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        --local argument = self.controller.Argument
        --if not isNull(argument.parameters) then
            self.curForgingGrade = ForgingComponent.curForgingGrade--argument.parameters.curForgingGrade
            self.forgingQuestVo = self:GetForgingQuestVo()
            local forgingGradeData = CfUtils.GetCfVo(AutoIds.IdSetting1821, "ForgingGradeVo", self.curForgingGrade)
            for k, v in pairs(self.forgingQuestVo) do
                if v.id == forgingGradeData.region then
                    self.selectedChallengeIndex = k
                end
            end
            SetButtonAction(self.BtnArrowLeft.transform, function ()
                if self.selectedChallengeIndex == 1 then
                    GameUtils.Toast(localize("当前已经是最低难度"))
                    return
                end
                self.selectedChallengeIndex = self.selectedChallengeIndex - 1
                self:FreshChallengePanel()
            end)
            SetButtonAction(self.BtnArrowRight.transform, function ()
                if self.forgingQuestVo[self.selectedChallengeIndex].regionLevel - 1 == #self.forgingQuestVo then
                    GameUtils.Toast(localize("当前已经是最高难度"))
                    return
                else
                    if self.forgingQuestVo[self.selectedChallengeIndex].regionLevel <= self.curForgingGrade then

                    else
                        GameUtils.Toast(localize("通关当前挑战后解锁"))
                        return
                    end
                end
                self.selectedChallengeIndex = self.selectedChallengeIndex + 1
                self:FreshChallengePanel()
            end)
            SetButtonAction(self.FontStyleButtonChallenge, function ()
                --进入编队
                self.controller:SetBackArgument(true)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = {levelId = self.forgingQuestVo[self.selectedChallengeIndex].id}}, {
                    {id = Constants.UITypeIds.ForgingDialog},
                    {id = Constants.UITypeIds.ForgingChallengePopup},
                })
            end)
            self:FreshChallengePanel()
        --end
    end))
    return coWait
end

function ForgingChallengePopup:FreshBaseUI()

end

function ForgingChallengePopup:FreshChallengePanel()
    --print("----->>"..self.selectedChallengeIndex)
    local forgingGradeData = CfUtils.GetCfVo(AutoIds.IdSetting1821, "ForgingGradeVo", self.forgingQuestVo[self.selectedChallengeIndex].regionLevel - 1)
    local forgingGradeQuestData = self.forgingQuestVo[self.selectedChallengeIndex]
    self.Text.text = forgingGradeQuestData.name
    self.TextNumberLeft1.text = forgingGradeData.maxNormal
    self.TextNumberLeft2.text = forgingGradeData.maxActivity
    local nextIndex = self.forgingQuestVo[self.selectedChallengeIndex].regionLevel
    local nextForgingGradeData = CfUtils.GetCfVo(AutoIds.IdSetting1821, "ForgingGradeVo", nextIndex)
    self.TextNumberRight1.text = nextForgingGradeData.maxNormal
    self.TextNumberRight2.text = nextForgingGradeData.maxActivity
    local isMaxDifficult = self.forgingQuestVo[self.selectedChallengeIndex].regionLevel - 1 == #self.forgingQuestVo
    local isRepeat = forgingGradeData.id < self.curForgingGrade or (isMaxDifficult and self.curForgingGrade == self.forgingQuestVo[self.selectedChallengeIndex].regionLevel)--or forgingGradeData.region == nextForgingGradeData.region
    ---挑战成功以后，按钮文本改为  重复挑战  透明度改为30%
    self.DescribeGroup.alpha = isRepeat and 0.3 or 1
    self.FontStyleButtonChallenge:GetComponent(typeof(FontStyleButton)):ResetFontStyle("B1", isRepeat and localize("重复挑战") or localize("挑战"))
    self.BtnArrowLeft.Status = self.selectedChallengeIndex == 1 and 2 or 1--2不可点击 1可点击
    local rightStatus = self.forgingQuestVo[self.selectedChallengeIndex].regionLevel - 1 == #self.forgingQuestVo or self.forgingQuestVo[self.selectedChallengeIndex].regionLevel > self.curForgingGrade
    self.BtnArrowRight.Status = rightStatus and 2 or 1
end

