function ForgingChallengePopup:GetForgingQuestVo()
    local voList = CfUtils.GetWholeVo(AutoIds.IdSetting1822, "ForgingQuestVo")
    table.sort(voList, function (a,b)--按等级进行排序
        if a.id ~= b.id then
            return a.id < b.id
        end
    end)
    return voList
end

function ForgingChallengePopup:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return ForgingChallengePopup